PAGE = dict(
    slug='radial',
    title='Pane::radial',
    signature='Trace& Pane::radial(Series theta, Series radius)',
    intro='Adds a **polar trace**: points given by an angle and a distance from the centre, joined in the order given. It is the trace of radar (spider) charts and of curves written in polar form. `theta` is in **radians**, counted anticlockwise from the direction of the positive x axis (to the right); `radius` is the distance from the centre, in the units of the pane. The trace is an open line: repeat the first point at the end to close a shape. A pane that holds only radial traces is drawn as a round plot with rings and spokes instead of x and y axes.\n\n`theta` and `radius` have the same length, or one of them has length 1.',
    parameters='**theta** (`Series`-convertible)\n    The angles, in radians.\n\n**radius** (`Series`-convertible)\n    The distances from the centre.',
    returns='`Trace&`\n    The new trace.',
    examples=[
        dict(id='basic', text='Angle and radius for each point, the angle in radians counted anticlockwise from the right. Five points at equal angles of a fifth of a turn, with their radii.',
             code='auto fig = studio("radial_basic");\nauto& pane = fig.pane2("p");\nstd::vector<double> theta, radius{3, 5, 2, 4, 5};\nfor (int i = 0; i < 5; ++i) theta.push_back(2.0 * 3.141592653589793 * i / 5.0);\npane.radial(theta, radius);\nfig.save_svg("figure.svg");'),
        dict(id='closed', text='The points are joined in the order given and the last is not joined to the first. To close a shape, repeat the first point at the end: the second figure is closed.',
             code='auto fig = studio("radial_closed");\nfig.mosaic(1, 2);\nstd::vector<double> theta, radius{3, 5, 2, 4, 5};\nfor (int i = 0; i < 5; ++i) theta.push_back(2.0 * 3.141592653589793 * i / 5.0);\nauto& open = fig.pane2("open");\nopen.radial(theta, radius);\ntheta.push_back(theta.front());\nradius.push_back(radius.front());\nauto& closed = fig.pane2("closed");\nclosed.radial(theta, radius);\nfig.save_svg("figure.svg");'),
        dict(id='rose', text='Many points make a smooth curve: a three-petal rose, `r = 1 + cos(3 theta)`, sampled every 5 degrees (theta in radians).',
             code='auto fig = studio("radial_rose");\nauto& pane = fig.pane2("p");\nstd::vector<double> theta, radius;\nfor (int degrees = 0; degrees <= 360; degrees += 5) {\n  const double t = degrees * 3.141592653589793 / 180.0;\n  theta.push_back(t);\n  radius.push_back(1.0 + std::cos(3.0 * t));\n}\npane.radial(theta, radius);\nfig.save_svg("figure.svg");'),
        dict(id='two', text='Two traces on one polar pane, to compare two profiles on the same scale: six directions each, both closed.',
             code='auto fig = studio("radial_two");\nauto& pane = fig.pane2("p");\nstd::vector<double> theta;\nfor (int i = 0; i <= 6; ++i) theta.push_back(2.0 * 3.141592653589793 * i / 6.0);\npane.radial(theta, std::vector<double>{4, 5, 3, 4, 2, 5, 4}).label("this year");\npane.radial(theta, std::vector<double>{2, 3, 4, 2, 4, 3, 2}).label("last year");\npane.legend(KeyPlace::NorthEast);\nfig.save_svg("figure.svg");'),
        dict(id='broadcast', text='A single radius is repeated for every angle: points on a circle of that radius, here 33 points around it.',
             code='auto fig = studio("radial_circle");\nauto& pane = fig.pane2("p");\nstd::vector<double> theta;\nfor (int i = 0; i <= 32; ++i) theta.push_back(2.0 * 3.141592653589793 * i / 32.0);\npane.radial(theta, std::vector<double>{4});\nfig.save_svg("figure.svg");'),
        dict(id='errors', text='Inputs that cannot be drawn are refused when the trace is added, and the message names the method and the problem. The pane keeps the traces it had.',
             code='auto report = [](const char* what, auto&& call) {\n  auto fig = studio("radial_errors");\n  auto& pane = fig.pane2("p");\n  try {\n    call(pane);\n    std::cout << what << ": accepted\\n";\n  } catch (const pluss::Error& e) {\n    std::cout << what << ": " << e.message() << "\\n";\n  }\n};\nreport("lengths differ", [](Pane& pane) { pane.radial(std::vector<double>{0, 1.5, 3}, std::vector<double>{1, 2}); });\nauto fig = studio("radial_errors_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{0, 1}, std::vector<double>{0, 1});\nfig.save_svg("figure.svg");'),
        dict(id='wrong_pane', text='`radial` needs a planar pane. On a volumetric pane it throws at once, naming the kind it needs, and nothing is added.',
             code='auto fig = studio("radial_wrong_pane");\nauto& pane = fig.pane3("p");\ntry {\n  pane.radial(std::vector<double>{0, 1}, std::vector<double>{1, 2});\n} catch (const pluss::Error& e) {\n  std::cout << e.message() << "\\n";\n}\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- Returns the new [`Trace&`](../trace/label.md); the reference stays valid for the life of the pane, and the style calls of the trace ([`label`](../trace/label.md), [`stroke`](../trace/stroke.md), [`width`](../trace/width.md), ...) chain off it.\n- The data is copied into the trace when it is added, so changing the vector afterwards does not change the figure.\n',
    see=['[`Pane::trend`](trend.md): points on x and y axes.'],
)
